    goToFirstPage() {
        this.onPageChange(0);
    }
    goToPreviousPage() {
        this.onPageChange(this.currentPage - 1);
    }
    goToNextPage() {
        this.onPageChange(this.currentPage + 1);
    }
    goToLastPage() {
        this.onPageChange(this.totalPages - 1);
    }
